import {keyName,formatSeconds,correctAnswer,validateLevel,scoreMatch,soloSummary} from './core.js';
import {esc,editorSvg,boardSvg} from './renderer.js';
import {FAMILY_NAMES} from './generator.js';
import {rateLevel,TIER_NAMES} from './difficulty.js';
const tierOptions=TIER_NAMES.map((name,i)=>[i+1,`${i+1} · ${name}`]);
const difficultyLabel=l=>{const r=rateLevel(l);return `Tier ${r.tier} · ${r.label} · ${r.score}/100`;};
function ratingCard(l){const r=rateLevel(l),names={count:'Box count',stacking:'Stacking',shapes:'Shape variety',spread:'Board spread',exposure:'Viewing time',motion:'Movement speed'};return `<div class="rating-card"><strong>${difficultyLabel(l)}</strong><meter min="0" max="100" value="${r.score}" aria-label="Puzzle difficulty score">${r.score}</meter><details><summary>What makes this puzzle difficult?</summary><dl>${Object.entries(r.parts).map(([k,v])=>`<div><dt>${names[k]}</dt><dd>${v} points</dd></div>`).join('')}</dl><p class="small-copy">A design estimate based on the layout and timing, not a measured skill rating.</p></details></div>`;}

const button=(action,text,attrs='',primary=false)=>`<button class="action ${primary?'primary':''}" data-action="${action}" ${attrs}>${text}</button>`;
const options=(items,selected)=>items.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(t)}</option>`).join('');
const field=(name,title,content)=>`<label class="form-field" for="${name}"><span>${title}</span>${content}</label>`;
export function availableLevels(ctx){return [...ctx.pack.levels.map((l,i)=>({key:`reference:${i}`,label:`Reference · ${i+1}. ${l.name}`,level:l})),...ctx.videoPack.levels.map((l,i)=>({key:`video:${i}`,label:`Video · ${i+1}. ${l.name}`,level:l})),...ctx.store.levels.map(l=>({key:`saved:${l.id}`,label:`My levels · ${l.name}`,level:l})),...ctx.store.packs.flatMap(p=>p.levels.map((l,i)=>({key:`pack:${p.id}:${i}`,label:`${p.title} · ${i+1}. ${l.name}`,level:l})))];}
export function renderUI(ctx){
  const {screen,store,ui,engine,pack}=ctx,b=store.settings.bindings;
  if(screen==='menu')return {cls:'active menu complete-menu',html:`<div class="menu-panel"><p class="eyebrow">Two players · ${ui.touch?'one phone':'one keyboard'}</p><h1>Count what<br>you saw.</h1><p class="intro">Remember the boxes. Tally your answer. A mistake adds five seconds; the lower total time wins.</p><div class="mode-grid">
    ${[['classic','Classic','10 researched rounds'],['quick','Quick match','5 fresh puzzles'],['full','Full match','20 fresh puzzles'],['endless','Endless practice','Keep going at your pace'],['practice','Choose a puzzle','Practice any saved level'],['custom','Custom match','Choose your rules and pack'],['video','Video challenge','12 layouts from the footage'],['ladder','Pattern ladder','New shapes as you advance'],['motion','Motion gauntlet','Moving rows, towers and gaps'],['duel','Endless duel','Win by a customizable lead'],['climb','Difficulty climb','A customizable ramp through 10 tiers']].map(([mode,title,copy])=>`<button class="mode-card ${mode==='classic'?'featured':''}" data-action="mode" data-mode="${mode}"><strong>${title}</strong><span>${copy}</span></button>`).join('')}
    </div>${ui.touch?'<div class="key-legend touch-legend">Touch controls ready · Player 1 left · Player 2 right</div>':`<div class="key-legend"><span>P1 <kbd>${esc(keyName(b.p1Count))}</kbd> count <kbd>${esc(keyName(b.p1Submit))}</kbd> done</span><span>P2 <kbd>${esc(keyName(b.p2Count))}</kbd> count <kbd>${esc(keyName(b.p2Submit))}</kbd> done</span></div>`}<div class="menu-links">${button('generator','Puzzle generator')}${button('editor','Create a level')}${button('library','My levels and packs')}${button('history','Match history')}${button('help','How to play')}</div></div>`};
  if(screen==='setup'){
    const c=ui.setup,mode=c.mode,names={quick:'Quick match',full:'Full match',endless:'Endless practice',practice:'Choose a puzzle',custom:'Custom match',video:'Video challenge',ladder:'Pattern ladder',motion:'Motion gauntlet',duel:'Endless duel',climb:'Difficulty climb'};
    return {cls:'active form-screen',html:`<div class="form-panel"><p class="eyebrow">Choose the challenge</p><h2>${names[mode]}</h2><form id="setup-form"><div class="form-grid">
      ${['endless','practice','duel'].includes(mode)?'':field('players','Players',`<select id="players" name="players">${options([['2','Two players'],['1','Solo']],c.players)}</select>`)}
      ${mode==='practice'?field('practiceLevel','Puzzle',`<select id="practiceLevel" name="practiceLevel">${options(availableLevels(ctx).map(l=>[l.key,l.label]),c.practiceLevel)}</select>`):''}
      ${mode==='custom'?field('source','Puzzle source',`<select id="source" name="source">${options([['generated','Fresh generated puzzles'],['reference','Reference pack'],['video','Video challenge pack'],...store.packs.map(p=>[`pack:${p.id}`,p.title])],c.source)}</select>`):''}
      ${['custom','ladder','motion','climb'].includes(mode)?field('rounds','Number of rounds',`<input id="rounds" name="rounds" type="number" min="1" max="50" value="${c.rounds}" required>`):''}
      ${['practice','video','climb'].includes(mode)?'':field('difficulty','Difficulty',`<select id="difficulty" name="difficulty">${options([['gentle','Gentle'],['standard','Standard'],['intense','Intense']],c.difficulty)}</select>`)}
      ${['endless','duel','climb'].includes(mode)?field('family','Puzzle style',`<select id="family" name="family">${options([['mixed','A mix of styles'],...Object.entries(FAMILY_NAMES)],c.family)}</select>`):''}
      ${['practice','video'].includes(mode)?'':field('seed','Puzzle seed',`<input id="seed" name="seed" maxlength="80" value="${esc(c.seed)}" required>`)}
      ${mode==='climb'?`${field('startTier','Starting tier',`<select id="startTier" name="startTier">${options(tierOptions,c.startTier)}</select>`)}${field('maxTier','Maximum tier',`<select id="maxTier" name="maxTier">${options(tierOptions,c.maxTier)}</select>`)}${field('tierStep','Tiers added per rise',`<input id="tierStep" name="tierStep" type="number" min="1" max="9" value="${c.tierStep}" required>`)}${field('riseEvery','Rounds per rise',`<input id="riseEvery" name="riseEvery" type="number" min="1" max="20" value="${c.riseEvery}" required>`)}${field('ratedPresentation','Presentation',`<select id="ratedPresentation" name="ratedPresentation">${options([['auto','Automatic, motion at higher tiers'],['static','Stationary only'],['travel','Travelling only']],c.ratedPresentation)}</select>`)}`:''}
      ${mode==='climb'?'':field('previewMs','Viewing time',`<select id="previewMs" name="previewMs">${options([['0','Use each puzzle’s timing'],['750','0.75 seconds'],['1500','1.5 seconds'],['2500','2.5 seconds'],['5000','5 seconds']],c.previewMs)}</select>`)}
      ${['custom','duel'].includes(mode)?field('answerLimitMs','Answer limit',`<select id="answerLimitMs" name="answerLimitMs">${options([['0','Wait until everyone submits'],['5000','5 seconds'],['8000','8 seconds'],['15000','15 seconds'],['30000','30 seconds']],c.answerLimitMs)}</select>`):''}
      ${mode==='duel'?`${field('duelRule','Winning rule',`<select id="duelRule" name="duelRule">${options([['time','Adjusted-time lead (lower wins)'],['points','Round-points lead (higher wins)']],c.duelRule)}</select>`)}${field('timeLead','Time lead required, seconds',`<input id="timeLead" name="timeLead" type="number" min="1" max="120" step="1" value="${c.timeLead}" required>`)}${field('pointsLead','Point lead required',`<input id="pointsLead" name="pointsLead" type="number" min="1" max="20" value="${c.pointsLead}" required>`)}${field('minRounds','Minimum completed rounds',`<input id="minRounds" name="minRounds" type="number" min="1" max="50" value="${c.minRounds}" required>`)}${field('maxRounds','Round cap (0 = no cap)',`<input id="maxRounds" name="maxRounds" type="number" min="0" max="500" value="${c.maxRounds}" required>`)}`:''}
    </div>${mode==='duel'?`<label class="check-label"><input name="escalate" type="checkbox" ${c.escalate?'checked':''}> Increase difficulty every five rounds</label><p class="small-copy">Time rule: accumulated answer time plus five seconds per mistake; lower wins. Point rule: a correct answer beats a wrong one; when both are correct, the faster answer earns one point. Both wrong or equal correct times earn no point. Play continues until the chosen lead is reached after the minimum rounds, or the optional cap. Only the lead for the selected rule is used.</p>`:''}${mode==='climb'?'<p class="small-copy">Difficulty rises by your chosen number of tiers after each block of rounds, up to the maximum. More boxes, supported towers, shape variety, shorter exposures and faster movement create a broad ramp. Each round shows its actual 0–100 score. A fixed style or stationary view can limit the reachable tier; the actual rating always takes priority. Two players use the usual lower-time-wins rules; solo tracks accuracy.</p>':''}${mode==='video'?'<p class="small-copy">Two Nintendo UK promotional layouts, then all ten traced Hadski rounds. Geometry follows the frames; exposure and paths remain approximate.</p>':''}${['ladder','motion'].includes(mode)?'<p class="small-copy">Browser extension inspired by the footage. Difficulty rises every five rounds from your chosen starting difficulty. Pattern Ladder introduces gaps, broad boxes, stairs, hollow frames and checkerboards. Motion Gauntlet keeps every board travelling.</p>':''}${mode==='custom'?`<label class="check-label"><input name="shuffle" type="checkbox" ${c.shuffle?'checked':''}> Shuffle an authored pack</label><p class="small-copy">Authored packs play once through. The round count applies to generated puzzles.</p>`:''}<p class="small-copy">A large, unsegmented box counts as one. Separate boxes in a tower each count. The same seed and settings reproduce the generated puzzles. Travel timing stays long enough for every box to be visible.</p><div class="actions">${button('submit-setup','Check controls','type="submit"',true)}${button('menu','Back','type="button"')}</div></form></div>`};
  }
  if(screen==='generator'){
    const g=ui.generator;
    return {cls:'active form-screen scroll-screen',html:`<div class="wide-panel"><div class="page-top"><div><p class="eyebrow">Fresh puzzles, measured challenge</p><h2>Puzzle generator</h2></div>${button('menu','Back')}</div><form id="generator-form"><div class="form-grid">${field('generate-tier','Target difficulty tier',`<select id="generate-tier" name="tier">${options(tierOptions,g.tier)}</select>`)}${field('generate-count','Number of levels',`<input id="generate-count" name="count" type="number" min="1" max="50" value="${g.count}" required>`)}${field('generate-family','Shape style',`<select id="generate-family" name="family">${options([['mixed','A mix of styles'],...Object.entries(FAMILY_NAMES)],g.family)}</select>`)}${field('generate-presentation','Presentation',`<select id="generate-presentation" name="presentation">${options([['auto','Automatic, motion at higher tiers'],['static','Stationary only'],['travel','Travelling only']],g.presentation)}</select>`)}${field('generate-seed','Puzzle seed',`<input id="generate-seed" name="seed" value="${esc(g.seed)}" maxlength="80" required>`)}</div><p class="small-copy">The same seed and settings recreate the batch. The score estimates difficulty from six factors. Fixed styles can limit the reachable tier; the cards show the actual result. Every generated box has a fully clear face. Extra boxes and supported towers are added only when they keep all boxes visible.</p><div class="actions">${button('generate-batch','Generate puzzles','type="submit"',true)}${button('generator-seed','New seed','type="button"')}</div></form>${g.levels.length?`<div class="generated-toolbar"><h3>${g.levels.length} generated level${g.levels.length===1?'':'s'} · target tier ${g.generatedTier}</h3><div class="actions">${button('generated-pack','Save batch as pack','',true)}${button('generated-solo','Play batch solo')}${button('generated-duel','Play batch with two')}${button('generated-export','Export batch JSON')}</div></div><div class="generated-grid">${g.levels.map((l,i)=>`<article class="generated-card"><h3>${i+1}. ${esc(l.name)}</h3><svg viewBox="280 170 720 510" role="img" aria-label="Generated puzzle ${i+1} preview">${boardSvg(l,{greenCount:l.boxes.length})}</svg><p class="small-copy">${l.boxes.length} separate boxes · ${l.presentation.kind==='travel'?'Travelling':'Stationary'} · ${l.presentation.durationMs} ms · All boxes visible</p>${ratingCard(l)}<div class="actions">${button('generated-save',store.levels.some(saved=>saved.id===l.id)?'Saved':'Save level',`data-index="${i}" ${store.levels.some(saved=>saved.id===l.id)?'disabled':''}`)}${button('generated-edit','Edit copy',`data-index="${i}"`)}</div></article>`).join('')}</div>`:'<p class="empty-copy">Choose a target tier and generate your first batch.</p>'}</div>`};
  }
  if(screen==='checks'){
    const checkPlayer=p=>`<div class="check-player"><h3><span class="color-pip ${p?'p2':''}"></span>Player ${p+1}</h3>${[0,1].map(a=>`<div class="check-row">${ui.touch?`<button type="button" class="check-touch ${p?'p2':''}" data-touch-action="${a?'submit':'count'}" data-player="${p}" aria-label="Check Player ${p+1} ${a?'submit':'count'} button">${a?'Submit':'Count +1'}</button>`:`<span>Press <kbd>${esc(keyName(b[`${p?'p2':'p1'}${a?'Submit':'Count'}`]))}</kbd> ${a?'to submit':'to count'}</span>`}<span class="checkmark ${ui.checked[p*2+a]?'done':''}">${ui.checked[p*2+a]?'✓':'○'}</span></div>`).join('')}</div>`;
    const ready=ui.checked[0]&&ui.checked[1]&&(ui.config.solo||ui.checked[2]&&ui.checked[3]);
    return {cls:'active check',html:`<div class="check-panel"><p class="eyebrow">${esc(ui.config.label)}</p><h2>Check your ${ui.touch?'buttons':'keys'}</h2><p class="panel-copy">${ui.touch?'Tap Count and Submit for each player. Holding counts once. You can play without a keyboard.':'Tap your count key and submit key. Each press adds one; holding never repeats.'}</p><div class="check-grid">${checkPlayer(0)}${ui.config.solo?'':checkPlayer(1)}</div><div class="actions center-actions">${button('start','Start counting',ready?'':'disabled',true)}${button('settings','Change controls')}${button('menu','Back')}</div></div>`};
  }
  if(screen==='paused')return {cls:'active paused',html:`<div class="pause-panel"><p class="eyebrow">Game paused</p><h2>Take your time</h2><p class="panel-copy">Finished rounds keep their times. An interrupted puzzle restarts with a replacement${engine.config.source==='authored'?'; authored puzzles restart as assisted practice':''}.</p><div class="actions center-actions">${button('resume','Resume','',true)}${engine.config.endless&&!engine.config.duel?button('finish-practice','Finish practice'):''}${button('menu','Leave session')}</div></div>`};
  if(screen==='results'){
    const result=engine.result(),solo=engine.config.solo;
    const cols=solo?`<div class="solo-stat-grid"><div><strong>${result.correct} / ${result.total}</strong><span>Correct answers</span></div><div><strong>${result.accuracy}%</strong><span>Accuracy</span></div><div><strong>${formatSeconds(result.total?result.rawMs/result.total:0)}s</strong><span>Average answer time</span></div></div>`:[0,1].map(i=>{const p=result.players[i];if(engine.config.duel?.rule==='points')return `<div class="result-player ${i?'p2':''}"><h3>Player ${i+1}</h3><div class="result-status ${result.winner!==i?'other':''}">${result.winner===null?'Draw':result.winner===i?'Winner':'Runner up'}</div><div class="result-line"><span>Answer time</span><strong>${formatSeconds(p.rawMs)} sec</strong></div><div class="result-line"><span>Correct answers</span><strong>${p.correct} / ${engine.rounds.length}</strong></div><div class="result-line"><span>Missed answers</span><strong>${p.mistakes}</strong></div><div class="result-line total"><span>Points</span><span>${result.points[i]}</span></div></div>`;return `<div class="result-player ${i?'p2':''}"><h3>Player ${i+1}</h3><div class="result-status ${result.winner!==i?'other':''}">${result.winner===null?'Draw':result.winner===i?'Winner':'Runner up'}</div><div class="result-line"><span>Answer time</span><strong>${formatSeconds(p.rawMs)} sec</strong></div><div class="result-line"><span>Mistakes</span><strong>${p.mistakes} × 5 sec</strong></div><div class="result-line"><span>Penalty</span><strong>+${formatSeconds(p.penaltyMs)} sec</strong></div>${engine.config.duel?.rule==='points'?`<div class="result-line"><span>Round points</span><strong>${result.points[i]}</strong></div>`:''}<div class="result-line total"><span>${engine.config.duel?.rule==='points'?'Time':'Total'}</span><span>${formatSeconds(p.adjustedMs)} sec</span></div></div>`;}).join('');
    return {cls:'active result scroll-screen',html:`<div class="result-panel"><p class="eyebrow">${esc(engine.config.label)} · ${engine.rounds.length} round${engine.rounds.length===1?'':'s'} complete${engine.assisted?' · assisted':''}</p><h2>${solo?'Practice complete':result.winner===null?'It’s a draw.':`Player ${result.winner+1} wins.`}</h2>${engine.config.duel?`<p class="panel-copy">${result.reason==='lead'?`Required lead: ${result.rule==='points'?result.target+(result.target===1?' point':' points'):formatSeconds(result.target)+' seconds'}. Achieved lead: ${result.rule==='points'?result.lead+(result.lead===1?' point':' points'):formatSeconds(result.lead)+' seconds'} after ${engine.rounds.length} round${engine.rounds.length===1?'':'s'}.`:'The configured round cap was reached.'} ${result.rule==='points'?'Higher round points win.':'Lower adjusted time wins.'}</p>`:''}<div class="${solo?'':'result-grid'}">${cols}</div><div class="actions center-actions">${button('again',engine.config.endless&&engine.config.solo?'Practice again':'Play again','',true)}${button('details','Round details')}${ui.returnTo==='generator'?button('return-generator','Back to generator'):''}${ui.returnTo==='editor'?button('return-editor','Back to editor'):ui.returnTo==='library'?button('return-library','Back to library'):ui.returnTo==='history'?button('return-history','Back to history'):''}${button('menu','Main menu')}</div></div>`};
  }
  if(screen==='settings')return {cls:'active form-screen',html:`<div class="form-panel"><p class="eyebrow">Make it comfortable</p><h2>Settings</h2><div class="settings-controls"><h3>Keyboard controls</h3><p class="small-copy">Click a key, then press its replacement. Each action needs a different key.</p><div class="binding-grid">${Object.keys(b).map((k,i)=>`<div><span>Player ${i<2?1:2} ${i%2?'submit':'count'}</span>${button('bind',ui.captureKey===k?'Press a key…':esc(keyName(b[k])),`data-key="${k}"`)}</div>`).join('')}</div><div class="actions">${button('default-keys','Z / X and N / M')}${button('alternate-keys','A / S and K / L')}</div></div><form id="settings-form"><div class="settings-options">${field('inputMode','Game controls',`<select id="inputMode" name="inputMode">${options([['auto','Automatic: touch on phones'],['touch','Touch buttons on any device'],['keyboard','Keyboard and desktop buttons']],store.settings.inputMode??'auto')}</select>`)}<label class="check-label"><input name="sound" type="checkbox" ${store.settings.sound?'checked':''}> Sound effects</label>${field('volume','Volume',`<input id="volume" name="volume" type="range" min="0" max="1" step="0.05" value="${store.settings.volume}">`)}<label class="check-label"><input name="highContrast" type="checkbox" ${store.settings.highContrast?'checked':''}> Higher contrast</label><label class="check-label"><input name="reducedMotion" type="checkbox" ${store.settings.reducedMotion?'checked':''}> Replace travelling puzzles with stationary views</label><p class="small-copy">Changing motion marks the session as assisted. Audio cues are optional.</p></div><div class="actions">${button('save-settings','Save settings','type="submit"',true)}${button('settings-back','Back','type="button"')}</div></form></div>`};
  if(screen==='editor'){
    const e=ui.editor,l=e.level,selected=l.boxes.find(b=>b.id===e.selected),errors=validateLevel(l),volume=l.boxes.reduce((n,b)=>n+b.w*b.d*b.h,0);
    const properties=['x','y','z','w','d','h'].map(k=>field(`box-${k}`,({x:'X cell',y:'Y cell',z:'Bottom height',w:'Width',d:'Depth',h:'Height'})[k],`<input id="box-${k}" type="number" min="${['w','d','h'].includes(k)?1:0}" max="${k==='z'?3:['h'].includes(k)?4:5}" value="${selected?.[k]??(['w','d','h'].includes(k)?1:0)}">`)).join('');
    return {cls:'active editor-screen',html:`<div class="editor-panel"><div class="page-top"><div><p class="eyebrow">Create your own challenge</p><h2>Level editor</h2></div>${button('library','My library')}</div><div class="editor-layout"><div class="editor-left"><div class="editor-tools">${['add','select','delete'].map(tool=>button('editor-tool',tool==='add'?'Add box':tool==='select'?'Select':'Delete',`data-tool="${tool}" aria-pressed="${e.tool===tool}"`)).join('')}</div><svg id="editor-board" viewBox="0 0 1280 720" role="img" aria-label="Editable isometric box board">${editorSvg(l,e.selected,store.settings)}</svg><div class="editor-summary"><strong>${l.boxes.length} boxes</strong><span>${volume} occupied unit cells</span><span>${e.dirty?'Unsaved changes':'Saved'}</span></div><p class="small-copy">Click the ground to add a box. Click an existing box to select it, or add a unit box on top. Large boxes use the dimensions on the right.</p><div class="actions">${button('undo','Undo',e.undo.length?'':'disabled')}${button('redo','Redo',e.redo.length?'':'disabled')}${button('mirror','Mirror')}${button('rotate','Rotate')}${button('clear','Clear')}</div><div class="validation ${errors.length?'invalid':'valid'}" role="status">${errors.length?errors.slice(0,4).map(esc).join('<br>'):'Visibility checked: every box has a fully unobstructed face. Ready to play.'}</div></div><div class="editor-right">${ratingCard(l)}${field('level-name','Level name',`<input id="level-name" maxlength="80" value="${esc(l.name)}">`)}<h3>${selected?'Selected box':'New box dimensions'}</h3><div class="properties-grid">${properties}</div><div class="actions">${button('apply-box','Apply to selected',selected?'':'disabled')}${button('stack','Stack a unit box',selected?'':'disabled')}${button('duplicate-box','Duplicate',selected?'':'disabled')}${button('delete-box','Delete selected',selected?'':'disabled')}</div>${field('presentation','Presentation',`<select id="presentation">${options([['static','Stationary'],['travel','Travel across screen']],l.presentation.kind)}</select>`)}${field('view-duration','Viewing or travel duration in ms',`<input id="view-duration" type="number" min="${l.presentation.kind==='travel'?300:100}" max="10000" step="50" value="${l.presentation.durationMs}">`)}${l.presentation.kind==='travel'?field('travel-direction','Travel direction',`<select id="travel-direction">${options([['left','From right to left'],['right','From left to right']],l.presentation.from.x>0?'left':'right')}</select>`):''}<details><summary>Reveal order</summary><ol class="reveal-list">${l.revealOrder.map((id,i)=>`<li><span>${esc(id)}</span><button data-action="reveal-up" data-index="${i}" ${i?'':'disabled'} aria-label="Move ${esc(id)} earlier">↑</button><button data-action="reveal-down" data-index="${i}" ${i<l.revealOrder.length-1?'':'disabled'} aria-label="Move ${esc(id)} later">↓</button></li>`).join('')}</ol></details><div class="actions editor-save">${button('save-level',store.levels.some(s=>s.id===l.id)?'Save changes':'Save level',errors.length?'disabled':'',true)}${button('save-copy','Save as copy',errors.length?'disabled':'')}${button('test-level','Test solo',errors.length?'disabled':'')}${button('test-duel','Test with two',errors.length?'disabled':'')}${button('export-level','Export JSON',errors.length?'disabled':'')}</div><div class="actions">${button('blank-level','New blank level')}${button('generator','Puzzle generator')}</div></div></div></div>`};
  }
  if(screen==='library')return {cls:'active form-screen scroll-screen',html:`<div class="wide-panel"><div class="page-top"><div><p class="eyebrow">Saved on this browser</p><h2>My levels and packs</h2></div>${button('menu','Back')}</div><div class="actions library-actions">${button('editor','Create a level','',true)}${button('generator','Generate levels')}${button('new-pack','Build a pack')}<label class="action file-button">Import JSON<input id="pack-import" type="file" accept=".json,application/json" hidden></label></div>${field('library-tier','Difficulty filter',`<select id="library-tier">${options([['all','All difficulty tiers'],...tierOptions],ui.libraryTier??'all')}</select>`)}<h3>Levels <span class="muted">${store.levels.length}</span></h3>${store.levels.filter(l=>!ui.libraryTier||ui.libraryTier==='all'||rateLevel(l).tier===Number(ui.libraryTier)).length?store.levels.filter(l=>!ui.libraryTier||ui.libraryTier==='all'||rateLevel(l).tier===Number(ui.libraryTier)).map(l=>`<div class="library-row"><div><strong>${esc(l.name)}</strong><span>${difficultyLabel(l)} · ${l.boxes.length} boxes · ${l.presentation.kind==='travel'?'Travelling':'Stationary'} · ${l.presentation.durationMs} ms${validateLevel(l).length?' · Needs a visibility fix before play; edit or export it':''}</span></div><div class="actions">${button('edit-saved','Edit',`data-id="${esc(l.id)}"`)}${button('play-saved','Play',`data-id="${esc(l.id)}" ${validateLevel(l).length?'disabled':''}`)}${button('export-saved','Export',`data-id="${esc(l.id)}"`)}${button('delete-saved','Remove',`data-id="${esc(l.id)}"`)}</div></div>`).join(''):'<p class="empty-copy">No saved levels in this difficulty tier. Choose All difficulty tiers or generate a new level.</p>'}<h3>Packs <span class="muted">${store.packs.length}</span></h3>${store.packs.length?store.packs.map(p=>`<div class="library-row"><div><strong>${esc(p.title)}</strong><span>${p.levels.length} levels${p.levels.some(l=>validateLevel(l).length)?' · Contains a level that needs a visibility fix':''}</span></div><div class="actions">${button('play-pack','Play pack',`data-id="${esc(p.id)}" ${p.levels.some(l=>validateLevel(l).length)?'disabled':''}`)}${button('edit-pack','Edit',`data-id="${esc(p.id)}"`)}${button('export-pack','Export',`data-id="${esc(p.id)}"`)}${button('delete-pack','Remove',`data-id="${esc(p.id)}"`)}</div></div>`).join(''):'<p class="empty-copy">Build a pack from your levels, or import a version 1 JSON pack.</p>'}</div>`};
  if(screen==='pack-builder'){
    const draft=ui.packDraft;
    return {cls:'active form-screen scroll-screen',html:`<div class="wide-panel"><div class="page-top"><div><p class="eyebrow">Arrange a match</p><h2>Pack builder</h2></div>${button('library','Back')}</div>${field('pack-title','Pack title',`<input id="pack-title" maxlength="80" value="${esc(draft.title)}">`)}<div class="pack-add">${field('pack-add-level','Add a level',`<select id="pack-add-level">${options(availableLevels(ctx).map(l=>[l.key,l.label]),ui.packAddKey??'reference:0')}</select>`)}${button('pack-add','Add')}</div><div class="pack-order">${draft.levels.map((l,i)=>`<div class="library-row"><div><strong>${i+1}. ${esc(l.name)}</strong><span>${l.boxes.length} boxes · ${difficultyLabel(l)}</span></div><div class="actions">${button('pack-up','↑',`data-index="${i}" ${i?'':'disabled'} aria-label="Move level ${i+1} earlier"`)}${button('pack-down','↓',`data-index="${i}" ${i<draft.levels.length-1?'':'disabled'} aria-label="Move level ${i+1} later"`)}${button('pack-edit-level','Edit copy',`data-index="${i}"`)}${button('pack-remove','Remove',`data-index="${i}"`)}</div></div>`).join('')||'<p class="empty-copy">Add up to 50 levels and put them in the order you want to play.</p>'}</div><div class="actions">${button('save-pack','Save pack',draft.levels.length?'':'disabled',true)}${button('export-draft-pack','Export JSON',draft.levels.length?'':'disabled')}${button('test-pack','Play pack',draft.levels.length?'':'disabled')}</div></div>`};
  }
  if(screen==='history'){
    const history=store.history;
    return {cls:'active form-screen scroll-screen',html:`<div class="wide-panel"><div class="page-top"><div><p class="eyebrow">Your completed sessions</p><h2>Match history</h2></div>${button('menu','Back')}</div><p class="small-copy">The latest 100 sessions are kept locally, within the browser’s storage limit. Replays use the saved arrangements and are marked as practice.</p>${history.length?history.map(h=>`<div class="library-row"><div><strong>${esc(h.label)}${h.assisted?' · assisted':''}</strong><span>${new Date(h.date).toLocaleString()} · ${h.totalRounds??h.rounds.length} rounds${h.duel?.rule==='points'?` · ${h.summary.points.join('–')} points`:''} · ${h.solo?`${h.summary?.accuracy??soloSummary(h.rounds).accuracy}% correct`:h.summary?.winner===null?'Draw':`Player ${(h.summary?.winner??scoreMatch(h.rounds).winner??0)+1} won`}</span></div><div class="actions">${button('history-detail','Details',`data-id="${esc(h.id)}"`)}${button('replay','Replay practice',`data-id="${esc(h.id)}"`)}</div></div>`).join(''):'<p class="empty-copy">Finish a match or practice session to see it here.</p>'}</div>`};
  }
  if(screen==='details'){
    const record=ui.detailRecord,rounds=record?.rounds??engine.rounds,solo=record?.solo??engine.config.solo,points=(record?.duel??engine?.config.duel)?.rule==='points';
    return {cls:'active form-screen scroll-screen',html:`<div class="wide-panel"><div class="page-top"><div><p class="eyebrow">Answer by answer</p><h2>Round details</h2></div>${button('details-back','Back')}</div><div class="table-scroll"><table><thead><tr><th>Round</th><th>Boxes</th><th>Difficulty</th><th>Player 1</th><th>Time</th>${solo?'':'<th>Player 2</th><th>Time</th>'}</tr></thead><tbody>${rounds.map((r,i)=>`<tr><td>${r.round??i+1}</td><td>${r.answer}</td><td>${difficultyLabel(r.level)}</td>${r.players.slice(0,solo?1:2).map(p=>`<td>${p.guess??'No answer'} ${p.guess===r.answer?'✓':'✕'}</td><td>${formatSeconds(p.elapsedMs)}s${!solo&&!points&&p.guess!==r.answer?' + 5s':''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${record?.totalRounds>rounds.length?'<p class="small-copy">This long practice session keeps details for its latest 50 rounds.</p>':''}</div>`};
  }
  if(screen==='help')return {cls:'active form-screen scroll-screen',html:`<div class="form-panel help-panel"><p class="eyebrow">Every box counts</p><h2>How to play</h2><ol><li><strong>Watch.</strong> After the countdown, remember the separate boxes on the board. Towers count one per box. A large box without internal edges counts as one.</li><li><strong>Count.</strong> When the board disappears, tap your count key once per box. P1 uses <kbd>${esc(keyName(b.p1Count))}</kbd>; P2 uses <kbd>${esc(keyName(b.p2Count))}</kbd>. The counter starts at zero and goes up to 99.</li><li><strong>Lock your answer.</strong> P1 presses <kbd>${esc(keyName(b.p1Submit))}</kbd>; P2 presses <kbd>${esc(keyName(b.p2Submit))}</kbd>. You cannot change a locked answer. Your own timer stops immediately.</li><li><strong>See the reveal.</strong> After everyone submits, each box turns green and the correct total appears. A check means correct; a cross means wrong.</li><li><strong>Win the match.</strong> Your answer times are added together, with five seconds for each mistake. The lower total wins. Equal totals to the displayed hundredth of a second are a draw. Solo practice reports accuracy and average time.</li></ol><h3>Choose your game</h3><p>Classic plays the ten reconstructed reference puzzles. Quick and Full create five or twenty fresh puzzles. Endless is solo practice until you choose Finish practice. Choose a puzzle plays any saved arrangement. Custom lets you choose a pack, round count, viewing time, and optional answer deadline. Missing a deadline counts as a mistake.</p><h3>New challenges and Endless Duel</h3><p>Video Challenge contains twelve manually traced formations from the downloaded footage. Pattern Ladder introduces unusual shapes as difficulty rises. Motion Gauntlet combines travelling towers, large boxes, separated rows and gaps. Endless Duel ends when one player reaches the configured lead after the minimum rounds. Choose an adjusted-time lead or round points, an answer deadline, gradual difficulty, and an optional round cap. A correct answer earns a point over a wrong answer; if both are correct, the faster player earns one. Both wrong or equal correct times give neither player a point.</p><h3>Phone controls</h3><p>Phones automatically show touch controls. In two-player games, Player 1 uses the left Count and Submit buttons, and Player 2 uses the right pair. In solo play, Count is on the left and Submit on the right. Tap once per box; holding adds only one. Buttons open after the viewing phase and lock independently on submission. Tap the buttons in the initial control check to start without a keyboard. Rotate for more room; Settings also lets you force touch controls on any device or keep desktop controls.</p><h3>Pause and accessibility</h3><p>Escape, switching tabs, or losing focus pauses play. An unfinished generated puzzle is replaced when you resume. Authored puzzles restart mirrored and mark the session as assisted. Finished rounds keep their times. Settings lets you remap keys, mute audio, raise contrast, or replace travel with a stationary view.</p><h3>Puzzle generator and Difficulty Climb</h3><p>Generate 1–50 puzzles with a seed, target tier 1–10, shape style and presentation. Inspect each puzzle’s actual 0–100 score and its count, stacking, shape, spread, exposure and speed factors. Save a single level, save the batch as a pack, edit a copy, or play it. Your library can filter levels by their calculated tier. Difficulty Climb raises the requested tier every chosen block of rounds up to your maximum, for solo or two players. Ratings are design estimates, not research-based player skill measurements; restrictive styles may fall below the requested tier.</p><h3>Make and keep puzzles</h3><p>The editor supports separate boxes, large boxes, and supported towers. Every box must have a fully unobstructed face; obscured arrangements cannot be saved, imported or played. Old saved layouts are preserved for repair or export, with play disabled until they pass the check. Save levels, arrange packs, and export JSON backups. Your library and match history are stored in this browser; use exports to move packs to another device. Replays are marked as practice.</p><p class="small-copy">An independent browser recreation of the Box Counting minigame in Dr Kawashima’s Brain Training for Nintendo Switch, based on <a href="https://www.youtube.com/watch?v=2SR6dQM1BDc" target="_blank" rel="noopener">recorded gameplay</a>. Geometry and audio are made for this version. Reconstructed layouts and some timings are approximate.</p><div class="actions">${button('menu','Back to game','',true)}</div></div>`};
  if(screen==='error')return {cls:'active error',html:`<div class="error-panel"><h2>Couldn’t load the game</h2><p>${esc(ui.error)}</p><p>Start the local server and reload this page.</p></div>`};
  return {cls:'',html:''};
}
